const metas = $('Build LLM prompt').all();
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const pairs = [];

$input.all().forEach((item, i) => {
  const meta = metas[i].json;
  let results = [];
  try {
    results = JSON.parse(item.json.choices[0].message.content).results || [];
  } catch (e) {
    return;   // bad JSON: no LLM matches for this product
  }
  for (const r of results) {
    if (r.eligible === true && meta.idMap[r.id]) {
      for (const uid of meta.idMap[r.id]) {
        if (UUID.test(uid)) pairs.push({ user_id: uid, product_id: Number(meta.product_id) });
      }
    }
  }
});

return [{ json: { pairs } }];   // always exactly one item

const items = $input.all();

const matchCount = items.filter(item => item.json.match_id !== undefined).length;
const batchId = $('Webhook').first().json.body.batch_id;

return [
  {
    json: {
      batch_id: batchId,
      match_count: matchCount,
    },
  },
];

const rows = $input.all().map(i => i.json);

const system = `You judge personal loan eligibility.
Return ONLY JSON: {"results":[{"id":"p1","eligible":true}]}.
Rules: judge each profile ONLY against the criteria text and the profile fields given.
If the profile does not clearly satisfy the criteria, set eligible to false. Include every profile id.`;

const normEmp = (e) => {
  const t = String(e || '').toLowerCase().trim();
  const m = {'salaried professional':'salaried','self employed':'self-employed','self employed professional':'self-employed','self-employed professional':'self-employed','business owner':'business','entrepreneur':'business'};
  return m[t] || t;
};

const byProduct = {};
for (const r of rows) {
  if (!byProduct[r.product_id]) {
    byProduct[r.product_id] = { product_id: r.product_id, name: r.product_name, criteria: r.criteria_text, rows: [] };
  }
  byProduct[r.product_id].rows.push(r);
}

return Object.values(byProduct).map(p => {
  const idMap = {};
  const profiles = p.rows.map((r, i) => {
    const id = 'p' + (i + 1);
    idMap[id] = r.user_ids;
    return { id, monthly_income: r.income_band, credit_score: r.score_band, employment: normEmp(r.employment) };
  });
  return { json: {
    product_id: p.product_id,
    system,
    user: `Product: ${p.name}\nCriteria: ${p.criteria}\nProfiles: ${JSON.stringify(profiles)}`,
    idMap,
  }};
});

const sql = $('Code in JavaScript3').first().json;
const llmCount = $input.all().filter((i) => i.json && i.json.match_id !== undefined).length;
return [{ json: { batch_id: sql.batch_id, match_count: sql.match_count + llmCount } }];
